mapper.select:
SELECT ua.user_id AS "userId", kps.personnel_no AS "personnelNo", kps.name AS "name", o.organization_name AS "organization", kps.position_name AS "position", kps.employment_status AS "employmentStatus", NULL AS "roleCodes", ua.use_yn AS "useYn", oum.position_name AS "positionTitle", kps.retirement_date AS "retirementDate", kps.last_synced_at AS "lastSyncedAt" FROM user_account ua JOIN korus_personnel_snapshot kps ON kps.personnel_no = ua.personnel_no LEFT JOIN organization o ON o.organization_code = kps.organization_code LEFT JOIN organization_user_mapping oum ON oum.user_id = ua.user_id AND oum.use_yn = 'Y'
AND kps.personnel_no LIKE CONCAT('%', #{criteria.personnelNo}, '%')
AND kps.name LIKE CONCAT('%', #{criteria.name}, '%')
AND o.organization_name LIKE CONCAT('%', #{criteria.organization}, '%')
AND kps.position_name = #{criteria.position}
AND kps.employment_status = #{criteria.employmentStatus}
AND EXISTS ( SELECT 1 FROM user_role ur WHERE ur.user_id = ua.user_id AND ur.role_code = #{criteria.roleCode} AND ur.status = 'ACTIVE' AND ur.effective_start_date <= current_date AND (ur.effective_end_date IS NULL OR ur.effective_end_date >= current_date) )
AND ua.use_yn = #{criteria.useYn}
ORDER BY kps.personnel_no

SELECT ua.user_id AS "userId", ua.use_yn AS "useYn"
FROM user_account ua
WHERE ua.user_id = #{userId}

mapper.update:
UPDATE user_account
SET use_yn = #{useYn}, updated_at = current_timestamp
WHERE user_id = #{userId}

mapper.insert:
INSERT INTO user_role (
  user_role_id, user_id, role_code, approval_user_id, effective_start_date, assignment_type, status
) VALUES (
  #{userRoleId}, #{userId}, #{roleCode}, #{actorUserId}, current_date, 'MANUAL', 'ACTIVE'
)

INSERT INTO change_history (
  change_history_id, entity_name, entity_id, before_value, after_value, actor_user_id, changed_at, reason, status
) VALUES (
  #{changeHistoryId}, #{entityName}, #{entityId}, CAST(#{beforeValue} AS jsonb), CAST(#{afterValue} AS jsonb),
  #{actorUserId}, current_timestamp, #{reason}, 'RECORDED'
)
